let isQuitRequested = false;
app.on("before-quit", () => {
    isQuitRequested = true;
});
mainWindow.on("close", (e) => {
    if (!isQuitAllowed) {
        e.preventDefault();
        if (!isQuitRequested && getTrayPreferences().closeToTray) {
            mainWindow.hide();
            return;
        }
        isQuitRequested = false;
        ipcWebContentsSend("quitApp", mainWindow.webContents, undefined);
    }
});

