// Keep left-click toggle behavior on non-Linux platforms
if (!isLinux) {
    trayInstance.on("click", () => {
        const mainWindow = getMainWindow();
        if (mainWindow) {
            showHideWindow(mainWindow);
        }
    });
}
else {
    // Linux XEmbed tray fires "click" on left-click; always bring the window
    // back and never hide on click, or an in-flight restore would be
    // minimized straight back into the tray.
    trayInstance.on("click", () => {
        const mainWindow = getMainWindow();
        if (mainWindow && !mainWindow.isVisible()) {
            if (mainWindow.isMinimized())
                mainWindow.restore();
            mainWindow.show();
            mainWindow.focus();
        }
    });
}

